#include <Arduino.h>

static bool ledOn = false;
static unsigned long lastToggle = 0;

void setup() {
  pinMode(13, OUTPUT);
  pinMode(A0, INPUT);
  digitalWrite(13, LOW);
  lastToggle = millis();
}

void loop() {
  const int raw = analogRead(A0);
  const unsigned long interval = 200UL + (1800UL * (unsigned long)raw) / 1023UL;
  const unsigned long now = millis();
  if (now - lastToggle >= interval) {
    lastToggle = now;
    ledOn = !ledOn;
    digitalWrite(13, ledOn ? HIGH : LOW);
  }
}
